   ```javascript
   const { Client, Intents } = require('discord.js');
   const { CommandoClient } = require('discord.js-commando');
   const client = new Client({ intents: [Intents.FLAGS.GUILDS] });
   const commando = new CommandoClient({ commandPrefix: '/', client });
   ```

