       aliases: ['b'],
       description: 'Bans a user from the server.',
       userPermissions: ['BAN_MEMBERS'],
       clientPermissions: ['BAN_MEMBERS'],
       args: [
         {
           id: 'user',
           type: 'member',
           prompt: '{c}Bitte wählen Sie einen Benutzer aus, den Sie bannten möchten.{/c}',
         },
         {
           id: 'reason',
           type: 'string',
           prompt: '{c}Bitte geben Sie eine Begründung für die Ban-Anforderung an.{/c}',
         },
