Hier ist eine C++-Funktion, die einen std::string mit Markdown-formatiertem Text als Eingabe nimmt und einen std::string mit HTML-formatiertem Text als Ausgabe zurückgibt:

```cpp
#include <string>
#include <sstream>
#include <vector>
#include <unordered_map>

// Mapping from Markdown syntax to HTML tags
const std::unordered_map<std::string, std::string> md2html{
    {"h1", "<h1>"},
    {"h2", "<h2>"},
    {"h3", "<h3>"},
    {"h4", "<h4>"},
    {"h5", "<h5>"},
    {"h6", "<h6>"},
    {"strong", "<strong>"},
    {"em", "<em>"},
    {"code", "<code>"},
    {"blockquote", "<blockquote>"},
    {"ul", "<ul>"},
    {"ol", "<ol>"},
    {"li", "<li>"},
    {"link", "<a href=\"[URL]\">[TEXT]</a>"}
};

std::string convertMarkdownToHTML(const std::string& markdown) {
    std::stringstream htmlStream;
    std::vector<std::string> lines = splitString(markdown, '\n');

    // Loop through each line and convert Markdown syntax to HTML
    for (const auto& line : lines) {
        std::vector<std::string> tokens = splitString(line, ' ');

        std::string token = tokens[0];
        std::string value = tokens.size() > 1 ? tokens[1] : "";

        // Handle headers
        if (token == "#") {
            int count = std::count(token.begin(), token.end(), '#');
            htmlStream << std::string(count, '<') << md2html["h" + std::to_string(count)] << '>';
            value = value.substr(2);
            htmlStream << value << "</" << md2html["h" + std::to_string(count)] << '>';
        }
        // Handle inline formatting
        else if (md2html.find(token) != md2html.end()) {
            htmlStream << md2html[token];
            value = value.substr(1, value.size() - 2);  // Remove any surrounding brackets
            htmlStream << value;
            htmlStream << "</" << md2html[token] << '>';
        }
        // Handle block formatting
        else if (token == "##") {
            htmlStream << "<h2>";
            value = value.substr(2);
            htmlStream << value << "</h2>";
        }
        else if (token == "###") {
            htmlStream << "<h3>";
            value = value.substr(3);
            htmlStream << value << "</h3>";
        }
        else if (token == "####") {
            htmlStream << "<h4>";
            value = value.substr(4);
            htmlStream << value << "</h4>";
        }
        else if (token == "#####") {
            htmlStream << "<h5>";
            value = value.substr(5);
            htmlStream << value << "</h5>";
        }
        else if (token == "######") {
            htmlStream << "<h6>";
            value = value.substr(6);
            htmlStream << value << "</h6>";
        }
        // Handle lists
        else if (token == "-") {
            htmlStream << "<li>";
            value = value.substr(2);
            htmlStream << value << "</li>";
        }
        else if (token == "*") {
            htmlStream << "<li>";
            value = value.substr(1);
            htmlStream << value << "</li>";
        }
        else if (token == "1. " || token == "2. " || token == "3. ") {
            htmlStream << "<li>";
            value = value.substr(3);
            htmlStream << value << "</li>";
        }
        else if (token == "[") {
            std::vector<std::string> linkParts = splitString(value, " ");
            std::string url = linkParts[0];
            std::string text = linkParts.size() > 1 ? linkParts[1] : url;
            htmlStream << md2html["link"].replace("[URL]", url).replace("[TEXT]", text);
        }
        // Handle blockquote
        else if (token == ">") {
            htmlStream << "<blockquote>";
            value = value.substr(1);
            htmlStream << value << "</blockquote>";
        }
        // Handle code block
        else if (token == "```") {
            htmlStream << "<pre><code>";
            value = value.substr(3);
            htmlStream << value << "</code></pre>";
        }
        else {
            htmlStream << value;
        }
        htmlStream << "\n";
    }

    std::string html = htmlStream.str();
    html.erase(html.find_last_not_of("\n") + 1);
    return html;
}

// Helper function to split a string into a vector of substrings
std::vector<std::string> splitString(const std::string& str, char delim) {
    std::stringstream ss(str);
    std::string item;
    std::vector<std::string> tokens;
    while (std::getline(ss, item, delim)) {
        tokens.push_back(item);
    }
    return tokens;
}
```

Dieser Code konvertiert einen Markdown-String in einen HTML-String. Die Funktion nimmt einen `std::string` mit Markdown-Text als Eingabe und gibt einen `std::string` mit HTML-Text als Ausgabe zurück. Die Konvertierung erfolgt durch die Verarbeitung jedes Zeilen- und Token-Paares und die Anwendung der passenden HTML-Tags. Die Funktionslogik wird durch die `md2html`-Konstante, die das Mapping von Markdown-Syntax zu HTML-Tags bereitstellt, unterstützt.

Die Funktion `splitString()` ist ein Hilfsfunktion, die eine Zeichenkette in eine Vektor von Unterzeichenketten aufteilt, basierend auf einem vorgegebenen Trennzeichen. Sie wird innerhalb der Hauptfunktion verwendet, um den Markdown-Text in seine einzelnen Zeilen und Token zu zerlegen.

